  const [shippingCost,setShippingCost]=useState(''); const [freeShippingThreshold,setFreeShippingThreshold]=useState(''); const [handlingMin,setHandlingMin]=useState(''); const [handlingMax,setHandlingMax]=useState(''); const [internationalShipping,setInternationalShipping]=useState(false); const [sku,setSku]=useState(''); const [stockQuantity,setStockQuantity]=useState('1'); const [lowStockThreshold,setLowStockThreshold]=useState('1');
  const [category, setCategory] = useState<string>(DEFAULT_CATEGORY);
